/**
 * Both engines over the source trees of the packages this checkout has installed.
 *
 * A corpus written by hand covers what its author thought of, and a codebase peq's
 * author did not write covers what nobody thought of: the constructs real libraries
 * reach for, in the proportions they reach for them. The dependencies already on
 * disk are such a codebase, and they cost nothing to obtain. They are not a fixed
 * list: a package that arrives tomorrow is read tomorrow.
 *
 * Reading all of them costs more memory than one process can hold, because the
 * reference engine keeps what it reflected over, so each package is read in a
 * process of its own.
 *
 * @internal
 */
#[CoversNothing]
#[Large]
#[RunTestsInSeparateProcesses]
final class InstalledPackageEquivalenceTest extends TestCase
{
    /**
     * @param string $package The name of the installed package
     * @param string $path    The source tree it keeps its code in
     *
     * @throws AnalysisFailedException If the reference engine cannot finish reading the package
     */
    #[DataProvider('providerInstalledPackages')]
    public function testBothEnginesDescribeTheSameGraphOfRealCode(string $package, string $path): void
    {
        $reference = GraphSnapshot::of((new PhpStanAnalyzer())->analyze($path));
        $candidate = GraphSnapshot::of((new NativeAnalyzer())->analyze($path));

        self::assertNotSame([], $reference->nodes, $package.' gives the engines nothing to disagree about');
        self::assertSame($reference->fingerprint(), $candidate->fingerprint(), $package.': '.$candidate->differenceFrom($reference)->describe());
    }

    /**
     * Finds the source tree of every installed package worth reading.
     *
     * A package is read at the directory it keeps its sources in rather than at its
     * root, so that its own tests and fixtures, which are written to be broken, are
     * not read as if they were library code. A package of fewer than eight files
     * exercises nothing a larger one does not, and each one read costs a whole run
     * of the reference engine.
     *
     * @return Generator<string, array{string, string}>
     */
    public static function providerInstalledPackages(): Generator
    {
        $vendor = dirname(__DIR__, 2).'/vendor';
        $packages = glob($vendor.'/*/*', GLOB_ONLYDIR);
        foreach ($packages === false ? [] : $packages as $package) {
            foreach (['src', 'lib', 'source'] as $directory) {
                $path = $package.'/'.$directory;
                if (!is_dir($path)) {
                    continue;
                }
                $files = new RegexIterator(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($path, FilesystemIterator::SKIP_DOTS)), '/\.php$/');
                if (iterator_count($files) < 8) {
                    continue;
                }

                $name = substr($package, strlen($vendor) + 1);
                $resolved = realpath($path);

                yield $name => [$name, $resolved === false ? $path : $resolved];

                break;
            }
        }
    }

    /**
     * Guards the sweep against reading nothing and reporting success.
     */
    public function testThereAreInstalledPackagesToRead(): void
    {
        self::assertNotSame([], iterator_to_array(self::providerInstalledPackages()), 'No installed package was read, so nothing about real code was checked.');
    }
}
<?php

declare(strict_types=1);

namespace App\Analyzer\NativeAnalyzer;

use App\Analyzer\Graph\NodeKind;
use App\Analyzer\NativeAnalyzer\Emitter\CallableEmitter;
use App\Analyzer\NativeAnalyzer\Emitter\MemberEmitter;
use PhpParser\Modifiers;
use PhpParser\Node as PhpParserNode;
use PhpParser\Node\Stmt;
use PhpParser\Node\Stmt\Class_;
use PhpParser\Node\Stmt\ClassConst;
use PhpParser\Node\Stmt\ClassLike;
use PhpParser\Node\Stmt\ClassMethod;
use PhpParser\Node\Stmt\EnumCase;
use PhpParser\Node\Stmt\Property;
use PhpParser\Node\Stmt\TraitUse;

/**
 * Walks the body of a class, an interface or an enum.
 *
 * What a class-like body declares is read here, in the order the reference engine
 * reads it — static methods first, the constructor next, properties last — because
 * that order decides which of two descriptions of the same symbol the graph keeps,
 * and a graph that kept the other one would not be the same graph.
 *
 * The statements a class takes on from a trait are read here too, once per using
 * class and as if they had been written in that class. Which of them are taken on at
 * all is not a question about the trait: it is PHP's own resolution, and
 * TraitFlattening answers it.
 *
 * @visibility namespace
 */
final class ClassWalker
{
    /**
     * The walk that reads what a method body reaches out to.
     */
    private readonly BodyWalker $bodies;

    /**
     * @param SourceIndex   $index    What the analysed files declare
     * @param GraphRecorder $recorder Where what the walk finds is collected
     * @param SourceWalker  $walker   The walk to hand anything that is not a class member back to
     */
    public function __construct(
        private readonly SourceIndex $index,
        private readonly GraphRecorder $recorder,
        private readonly SourceWalker $walker,
    ) {
        $this->bodies = new BodyWalker();
    }

    /**
     * Walks a class-like body.
     *
     * @param ClassLike     $node   The declaration whose body to walk
     * @param NodeKind      $kind   Which of the four kinds of declaration it is
     * @param string        $name   The name analysis knows it by
     * @param AnalysisScope $outer  Where the declaration itself is written
     * @param ParsedSource  $source The file being walked
     */
    public function walk(ClassLike $node, NodeKind $kind, string $name, AnalysisScope $outer, ParsedSource $source): void
    {
        $parent = $node instanceof Class_ && $node->extends !== null ? $node->extends->toString() : null;
        $scope = $outer->enteringClass($name, $parent !== null && $this->index->knowsClass($parent) ? $parent : null);

        foreach (self::inReadingOrder($node->stmts) as $statement) {
            $this->member($statement, $node, $kind, $scope, $source);
        }
    }

    /**
     * Puts the statements of a class-like into the order they are read in.
     *
     * @param array<Stmt> $statements The statements as they are written
     *
     * @return list<Stmt> The same statements, in reading order
     */
    public static function inReadingOrder(array $statements): array
    {
        usort($statements, static function (Stmt $first, Stmt $second): int {
            if ($first instanceof Property) {
                return 1;
            }
            if ($second instanceof Property) {
                return -1;
            }
            if (!$first instanceof ClassMethod || !$second instanceof ClassMethod) {
                return 0;
            }

            return [($first->flags & Modifiers::STATIC) === 0, strtolower($first->name->toString()) !== '__construct']
                <=> [($second->flags & Modifiers::STATIC) === 0, strtolower($second->name->toString()) !== '__construct'];
        });

        return $statements;
    }

    /**
     * Reads one statement of a class-like body.
     *
     * @param Stmt          $statement The statement to read
     * @param ClassLike     $class     The declaration it is read for, which is the using class for a trait statement
     * @param NodeKind      $kind      The kind of that declaration
     * @param AnalysisScope $scope     Where in the sources the walk stands
     * @param ParsedSource  $source    The file being walked
     */
    public function member(Stmt $statement, ClassLike $class, NodeKind $kind, AnalysisScope $scope, ParsedSource $source): void
    {
        if ($statement instanceof ClassMethod) {
            $this->method($statement, $class, $kind, $scope, $source);

            return;
        }
        if ($statement instanceof Property) {
            $this->recorder->record(MemberEmitter::properties($statement, $scope));

            return;
        }
        if ($statement instanceof ClassConst) {
            $this->recorder->record(MemberEmitter::constants($statement, $scope));

            return;
        }
        if ($statement instanceof EnumCase) {
            $this->recorder->record(MemberEmitter::enumCase($statement, $scope));

            return;
        }
        if ($statement instanceof TraitUse) {
            $this->traitUse($statement, $class, $kind, $scope);

            return;
        }

        $this->walker->descend($statement, $scope, $source);
    }

    /**
     * Reads one method declaration and its body.
     *
     * The relations a body writes are read from the file the class is written in
     * rather than from the statements held here, because a method reached through a
     * trait is written in another file entirely and the class's own file holds no
     * body for it.
     *
     * @param ClassMethod   $node   The method declaration
     * @param ClassLike     $class  The declaration it is read for
     * @param NodeKind      $kind   The kind of that declaration
     * @param AnalysisScope $scope  Where in the sources the walk stands
     * @param ParsedSource  $source The file being walked
     */
    public function method(ClassMethod $node, ClassLike $class, NodeKind $kind, AnalysisScope $scope, ParsedSource $source): void
    {
        $methodName = $node->name->toString();
        $reading = $scope->readingTrait();
        if ($reading !== null && !TraitFlattening::keepsMethod($class, $node, $methodName, $reading, $this->index)) {
            return;
        }

        $this->recorder->record(CallableEmitter::method($node, $scope, $kind));

        $inside = $scope->enteringMethod($methodName);
        foreach ($node->params as $param) {
            $this->recorder->record(CallableEmitter::promotedProperty($param, $scope));
            $this->walker->descend($param, $scope, $source);
        }

        $written = $this->index->sourceOf($scope->file);
        $body = $scope->className === null || $written === null ? null : $written->methodBody($scope->className, $methodName);
        if ($body !== null) {
            $this->recorder->record($this->bodies->relations($body, $inside));
        }

        foreach ($node->stmts ?? [] as $statement) {
            $this->walker->walk($statement, $inside, $source);
        }
    }

    /**
     * Reads the statements a class takes on from the traits one `use` names.
     *
     * A trait is followed only into a file the analysis was asked to read, and only
     * when it is not already being read further up: a trait that uses a trait that
     * uses it back is a cycle PHP rejects, and analysis has no reason to follow it.
     *
     * @param TraitUse      $node  The `use` statement met in the class body
     * @param ClassLike     $class The declaration it is written in
     * @param NodeKind      $kind  The kind of that declaration
     * @param AnalysisScope $scope Where in the sources the walk stands
     */
    public function traitUse(TraitUse $node, ClassLike $class, NodeKind $kind, AnalysisScope $scope): void
    {
        foreach ($node->traits as $trait) {
            $traitName = $trait->toString();
            $declaration = $this->index->classLike($traitName);
            if ($declaration === null || $declaration->kind !== NodeKind::Trait || $scope->isReading($declaration->name)) {
                continue;
            }

            $renames = TraitFlattening::renames($node, $traitName);
            $inside = $scope->enteringTrait($declaration->name);
            foreach ($declaration->node->stmts as $statement) {
                $this->member(self::renamed($statement, $renames, $node, $traitName), $class, $kind, $inside, $declaration->source);
            }
        }
    }

    /**
     * Returns a method statement under the name the using class takes it on as.
     *
     * A method renamed by an `as` is taken on under the new name and only under it,
     * so the statement is read as if that were the name it was written with.
     *
     * @param Stmt                  $statement The statement as the trait writes it
     * @param array<string, string> $renames   The new name of each renamed method
     *
     * @return Stmt The statement under the name the class takes it on as
     */
    public static function renamed(Stmt $statement, array $renames, ?TraitUse $use = null, ?string $trait = null): Stmt
    {
        if (!$statement instanceof ClassMethod) {
            return $statement;
        }
        $newName = $renames[strtolower($statement->name->toString())] ?? null;
        if ($newName === null && ($use === null || $use->adaptations === [])) {
            return $statement;
        }
        $renamedMethod = clone $statement;
        if ($newName !== null) {
            $renamedMethod->name = new PhpParserNode\Identifier($newName, $statement->name->getAttributes());
        }
        foreach ($use->adaptations ?? [] as $adaptation) {
            if ($adaptation instanceof Stmt\TraitUseAdaptation\Alias
                && $adaptation->newModifier !== null
                && strtolower($adaptation->method->toString()) === strtolower($statement->name->toString())
                && ($adaptation->trait === null || strtolower($adaptation->trait->toString()) === strtolower($trait ?? ''))
            ) {
                $renamedMethod->flags = ($renamedMethod->flags & ~Modifiers::VISIBILITY_MASK) | $adaptation->newModifier;
            }
        }

        return $renamedMethod;
    }
}
<?php

declare(strict_types=1);

namespace App\Analyzer\NativeAnalyzer;

use PhpParser\Node\Stmt\Class_;
use PhpParser\Node\Stmt\ClassLike;
use PhpParser\Node\Stmt\ClassMethod;
use PhpParser\Node\Stmt\TraitUse;
use PhpParser\Node\Stmt\TraitUseAdaptation\Alias;
use PhpParser\Node\Stmt\TraitUseAdaptation\Precedence;

/**
 * Which copy of a method a class taking traits on ends up with.
 *
 * A trait is not a symbol its methods belong to: the methods belong to every class
 * that uses it, and the graph records them there. Reading a trait's statements once
 * per using class is therefore the right thing to do — but only for the copies that
 * survive PHP's own rules. A class that writes a method keeps its own; two traits
 * offering the same method are settled by an `insteadof`; a method renamed by an `as`
 * is taken on under the new name and only under that one; and a trait that demands a
 * method rather than writing one is answered by whatever does write it, which may be
 * another trait or a class further up.
 *
 * Reading a copy PHP discards would record a method the class does not have, at the
 * line of a trait rather than of the class, which is why this is decided before a
 * trait statement is read rather than after.
 *
 * @visibility namespace
 */
final class TraitFlattening
{
    /**
     * Reads the renames one `use` statement applies to one trait.
     *
     * An adaptation naming no trait applies to every trait of the statement; one
     * naming a trait applies only to that trait.
     *
     * @param TraitUse $use       The `use` statement met while walking
     * @param string   $traitName Fully qualified name of the trait being read
     *
     * @return array<string, string> The new name of each renamed method, keyed by its lower-cased written name
     */
    public static function renames(TraitUse $use, string $traitName): array
    {
        $renames = [];
        foreach ($use->adaptations as $adaptation) {
            if (!$adaptation instanceof Alias || $adaptation->newName === null) {
                continue;
            }
            if ($adaptation->trait !== null && strtolower($adaptation->trait->toString()) !== strtolower($traitName)) {
                continue;
            }
            $renames[strtolower($adaptation->method->toString())] = $adaptation->newName->toString();
        }

        return $renames;
    }

    /**
     * Reports whether a class takes a trait's copy of a method on, or discards it.
     *
     * @param ClassLike   $class      The class-like reading the trait
     * @param ClassMethod $method     The method as the trait writes it
     * @param string      $methodName The name it is taken on as, after any rename
     * @param string      $traitName  Fully qualified name of the trait the copy is written in
     * @param SourceIndex $index      What the analysed files declare
     *
     * @return bool True when this copy is the one the class ends up with
     */
    public static function keepsMethod(ClassLike $class, ClassMethod $method, string $methodName, string $traitName, SourceIndex $index): bool
    {
        if (self::writesMethod($class, $methodName)) {
            return false;
        }

        $provider = self::providerOf($class, $methodName, $index);
        if ($provider === null || strtolower($provider) !== strtolower($traitName)) {
            return false;
        }

        return $method->stmts !== null || !self::inherits($class, $methodName, $index, []);
    }

    /**
     * Names the trait a class ends up taking a method from.
     *
     * A trait that writes the method answers for it before one that only demands it,
     * whatever order they are used in, because a demand is not an answer.
     *
     * @param ClassLike   $class      The class-like reading the traits
     * @param string      $methodName The method name, after any rename
     * @param SourceIndex $index      What the analysed files declare
     *
     * @return null|string The trait the method comes from, or null when no trait offers it
     */
    public static function providerOf(ClassLike $class, string $methodName, SourceIndex $index): ?string
    {
        $offers = self::offersOf($class, $methodName, $index);
        foreach ($offers as $offered) {
            if (!$offered->demanded) {
                return $offered->declaringTrait;
            }
        }

        return $offers === [] ? null : $offers[0]->declaringTrait;
    }

    /**
     * Reads every offer of a method the traits a class uses make, in the order they are used.
     *
     * An `insteadof` settles which trait a method is taken from, so the offers of
     * every other trait of that name are not offers at all.
     *
     * @param ClassLike   $class      The class-like reading the traits
     * @param string      $methodName The method name, after any rename
     * @param SourceIndex $index      What the analysed files declare
     *
     * @return list<TraitMethod> The offers that stand, in the order the traits are used
     */
    public static function offersOf(ClassLike $class, string $methodName, SourceIndex $index): array
    {
        $wanted = strtolower($methodName);
        $settled = null;
        $offers = [];

        foreach ($class->getTraitUses() as $use) {
            foreach ($use->adaptations as $adaptation) {
                if ($adaptation instanceof Precedence && $adaptation->trait !== null && strtolower($adaptation->method->toString()) === $wanted) {
                    $settled = strtolower($adaptation->trait->toString());
                }
            }
            foreach ($use->traits as $trait) {
                $through = $trait->toString();
                $offered = self::methodsOf($through, self::renames($use, $through), $index, [])[$wanted] ?? null;
                if ($offered !== null && ($settled === null || strtolower($through) === $settled)) {
                    $offers[] = $offered;
                }
            }
        }

        return $offers;
    }

    /**
     * Reports whether a class-like writes a method of the given name itself.
     *
     * @param ClassLike $class      The class-like being read
     * @param string    $methodName The method name, in any casing
     *
     * @return bool True when the declaration writes that method
     */
    public static function writesMethod(ClassLike $class, string $methodName): bool
    {
        return self::methodWritten($class, $methodName) !== null;
    }

    /**
     * Returns the method of that name a class-like writes, when it writes one.
     *
     * @param ClassLike $class      The class-like being read
     * @param string    $methodName The method name, in any casing
     *
     * @return null|ClassMethod The method it writes, or null when it writes none
     */
    public static function methodWritten(ClassLike $class, string $methodName): ?ClassMethod
    {
        $wanted = strtolower($methodName);
        foreach ($class->stmts as $statement) {
            if ($statement instanceof ClassMethod && strtolower($statement->name->toString()) === $wanted) {
                return $statement;
            }
        }

        return null;
    }

    /**
     * Reports whether a class has a written method of that name from further up.
     *
     * A trait that demands a method is answered by anything that writes one, and a
     * class that inherits a written method has already answered. Only what the
     * analysed files declare can be looked up; a class whose parent lives outside
     * them has nothing to be read here, which is also all the reference engine can
     * say about it.
     *
     * @param ClassLike    $class      The class-like being read
     * @param string       $methodName The method name, after any rename
     * @param SourceIndex  $index      What the analysed files declare
     * @param list<string> $seen       The ancestors already read, which stops a cycle
     *
     * @return bool True when something above the class writes that method
     */
    public static function inherits(ClassLike $class, string $methodName, SourceIndex $index, array $seen): bool
    {
        $parentName = $class instanceof Class_ && $class->extends !== null ? $class->extends->toString() : null;
        if ($parentName === null || in_array(strtolower($parentName), $seen, true)) {
            return false;
        }
        $seen[] = strtolower($parentName);

        $parent = $index->classLike($parentName);
        if ($parent === null) {
            return false;
        }

        $written = self::methodWritten($parent->node, $methodName);
        if ($written !== null) {
            return $written->stmts !== null;
        }

        $provider = self::providerOf($parent->node, $methodName, $index);
        foreach (self::offersOf($parent->node, $methodName, $index) as $offered) {
            if ($offered->declaringTrait === $provider && !$offered->demanded) {
                return true;
            }
        }

        return self::inherits($parent->node, $methodName, $index, $seen);
    }

    /**
     * Reads the methods a trait offers, following the traits it uses in turn.
     *
     * @param string                $traitName Fully qualified name of the trait
     * @param array<string, string> $renames   The renames the using statement applies to it
     * @param SourceIndex           $index     What the analysed files declare
     * @param list<string>          $reading   The traits already being read, which stops a cycle
     *
     * @return array<string, TraitMethod> What the trait offers, keyed by lower-cased method name
     */
    public static function methodsOf(string $traitName, array $renames, SourceIndex $index, array $reading): array
    {
        $declaration = $index->classLike($traitName);
        if ($declaration === null || in_array(strtolower($traitName), $reading, true)) {
            return [];
        }
        $reading[] = strtolower($traitName);

        $methods = [];
        foreach ($declaration->node->stmts as $statement) {
            if ($statement instanceof ClassMethod) {
                $written = strtolower($statement->name->toString());
                $methods[strtolower($renames[$written] ?? $written)] = new TraitMethod($declaration->name, $statement->stmts === null);
            }
        }

        foreach ($declaration->node->getTraitUses() as $use) {
            foreach ($use->traits as $nested) {
                $nestedName = $nested->toString();
                foreach (self::methodsOf($nestedName, self::renames($use, $nestedName), $index, $reading) as $name => $offered) {
                    $methods[$name] ??= $offered;
                }
            }
        }

        return $methods;
    }
}

